<script>
(function(){var T=(document.querySelector('meta[name=csrf-token]')||{}).content||'';
function post(u,b){return fetch(u,{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':T,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify(b)}).then(function(r){return r.json()})}
function box(html,onOk){var w=document.createElement('div');w.style.cssText='position:fixed;inset:0;background:rgba(15,31,61,.45);z-index:10000;display:flex;align-items:center;justify-content:center';w.innerHTML='<div style="background:#fff;border-radius:12px;padding:16px;width:min(440px,94vw);font-size:13px">'+html+'<div class="e" style="color:#B42318;font-size:12.5px;margin-top:6px"></div><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px"><button type="button" class="g x">বন্ধ করুন</button><button type="button" class="ok" style="background:#5B3FA6;color:#fff">সংরক্ষণ</button></div></div>';document.body.appendChild(w);w.querySelector('.x').onclick=function(){w.remove()};w.querySelector('.ok').onclick=function(){var b=this;b.disabled=true;onOk(w).then(function(k){if(k.success)location.reload();else{b.disabled=false;w.querySelector('.e').textContent=k.message||'Failed'}}).catch(function(){b.disabled=false;w.querySelector('.e').textContent='Failed'})}}
window.prSettle=function(id,val,carrier){box('<b>টাকার হিসাব</b><p style="color:#475467;font-size:12px;margin:4px 0 8px">ফেরত আসা পণ্যের মূল্য ৳'+val.toFixed(2)+' (মূল অর্ডারের প্রকৃত দাম ও ডিসকাউন্ট অনুযায়ী)। স্টক আগেই গ্রহণ হয়েছে; এটা আলাদা ধাপ।</p><label style="display:block;margin:4px 0">ধরন <select class="ty" style="width:100%"><option value="refunded">কাস্টমারকে টাকা ফেরত</option>'+(carrier?'<option value="adjusted">নতুন অর্ডারের পাওনার সঙ্গে সমন্বয়</option>':'')+'<option value="none">টাকা প্রযোজ্য নয়</option></select></label><label style="display:block;margin:4px 0">পরিমাণ (৳) <input type="number" class="am" min="0" step="0.01" value="'+val.toFixed(2)+'" style="width:100%"></label><label style="display:block;margin:4px 0">মাধ্যম (bKash, Cash…) <input type="text" class="me" maxlength="40" style="width:100%"></label><label style="display:block;margin:4px 0">নোট <input type="text" class="no" maxlength="300" style="width:100%"></label>',function(w){return post('/admin/orders/past-return/'+id+'/settle',{type:w.querySelector('.ty').value,amount:+w.querySelector('.am').value||0,method:w.querySelector('.me').value,note:w.querySelector('.no').value,order_id:carrier||null})})};
window.prVoid=function(id){box('<b>সংশোধন: এই গ্রহণ বাতিল</b><p style="color:#475467;font-size:12px;margin:4px 0 8px">ভুল এন্ট্রি হলে বাতিল করুন। যে স্টক যোগ হয়েছিল তা আবার বাদ যাবে। রেকর্ড মুছবে না, কারণসহ থেকে যাবে।</p><label style="display:block">কারণ <input type="text" class="rs" maxlength="300" style="width:100%"></label>',function(w){return post('/admin/orders/past-return/'+id+'/void',{reason:w.querySelector('.rs').value})})};
})();
</script>
@endif
